34	    it.todo("sword with enchantment 4 gets no high-enchantment surcharge");
35	    it.todo("cursed sword with enchantment 5 gets both surcharges");
36	    it.todo("customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
