41	
42	  describe("quote — modifier scope on multi-item policies", () => {
43	    it.todo(
44	      "cursed sword + plain amulet → 210 G before further modifiers and fee (curse applies to the cursed item's base premium only)",
45	    );
46	    it.todo("policy-wide modifiers apply to the sum of all item base premiums");
47	  });
48	
49	  describe("quote — rounding in the MHPCO's favor", () => {
50	    it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
