57	  });
58	
59	  describe("claim — standard reimbursement", () => {
60	    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
61	    it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
62	    it.todo("damage below the deductible → payout 0 G");
63	  });
64	
65	  describe("claim — special clauses", () => {
66	    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
67	    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full then deductible)");
